# model_phrases.py
# 評価項目ごとの「薬剤師の模範の言い方」（2026-11-12）
#
# 模範解答（evaluation.build_model_answer_prompt）で、学生の会話で足りなかった項目を補うときに、
# この言い方をそのまま使う。医学・薬学の説明・指導を毎回AIに作らせないための確定版。
#
# 作り方：課題の文面（処方内容・患者情報・正解・医師役の設定）を根拠に、
#   スタンダード・スキルアップ薬局の70課題は AI（Gemini）で下書きして私が見直し、
#   残りの63課題は私が書いた。課題の文面に無い医学的内容は、添付文書・学会の目安など
#   確かなものだけにし、一部は KEGG MEDICUS（JAPIC 添付文書）で照合した。
# 課題の文面や評価項目を変えたら、その課題の言い方も見直すこと。
# キーは「課題名|サブシナリオ名」→ {評価項目: 模範の言い方}

